import logging
import traceback
import random
import string

# Configure logging if not already configured
logging.basicConfig(level=logging.ERROR)

class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def _generate_error_code(self) -> str:
        """Generate a unique error reference code."""
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=8))

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            # Validate inputs
            if not isinstance(user, str) or not user.strip():
                error_code = self._generate_error_code()
                error_msg = f"Invalid user: user must be a non-empty string. Reference code: {error_code}"
                logging.error(f"Invalid user input for {user}: {error_msg}")
                if is_admin:
                    error_msg += f" Exception: ValueError('user must be a non-empty string')"
                return (400, error_msg)

            if not isinstance(item, str) or not item.strip():
                error_code = self._generate_error_code()
                error_msg = f"Invalid item: item must be a non-empty string. Reference code: {error_code}"
                logging.error(f"Invalid item input for {item}: {error_msg}")
                if is_admin:
                    error_msg += f" Exception: ValueError('item must be a non-empty string')"
                return (400, error_msg)

            if not isinstance(quantity, int) or quantity <= 0:
                error_code = self._generate_error_code()
                error_msg = f"Invalid quantity: quantity must be a positive integer. Reference code: {error_code}"
                logging.error(f"Invalid quantity input {quantity}: {error_msg}")
                if is_admin:
                    error_msg += f" Exception: ValueError('quantity must be a positive integer')"
                return (400, error_msg)

            # Try to reserve the item in inventory
            reservation_id = self.stock.reserve(item, quantity)

            # Success case
            confirmation_text = f"Order placed successfully! Your reservation ID is {reservation_id}."
            return (200, confirmation_text)

        except Exception as e:
            # Handle unexpected errors
            error_code = self._generate_error_code()

            # Log the full error with traceback
            logging.error(f"Unexpected error during order placement for user '{user}', item '{item}', quantity {quantity}. Reference code: {error_code}", exc_info=True)

            # Build user-facing message
            if is_admin:
                error_msg = f"An error occurred: {type(e).__name__}: {str(e)}. Reference code: {error_code}"
            else:
                error_msg = f"An error occurred. Please try again later. Reference code: {error_code}"

            # Return appropriate HTTP status code
            # For unexpected errors, use 500 (Internal Server Error)
            return (500, error_msg)
